import '../styles/quant-fidelity.css'
const route=useRoute(),market=shallowRef("aiQuant.templates.filterAll")
const section=computed(()=>route.params.section),mine=computed(()=>['mine','positions'].includes(route.params.id)),isFund=computed(()=>section.value==='quant-fund')
const funds=[{rate:.73,days:0,min:4999,max:99999,progress:83.6},{rate:1.25,days:7,min:100000,max:499999,progress:79.8},{rate:1.79,days:15,min:500000,max:999999,progress:75.9},{rate:2.35,days:30,min:1000000,max:4999999,progress:69.6},{rate:2.93,days:60,min:5000000,max:10000000,progress:52.8},{rate:3.55,days:90,min:10000000,max:100000000,progress:43.6}]
</script>
