><strong>{{ f.progress.toFixed(1) }}%</strong></div></div><div class="qf-tags"><template v-if="!f.days"><span class="accent">{{ $t("aiQuant.quantFund.card.tagFlexible") }}</span><span class="accent">{{ $t("aiQuant.quantFund.card.tagRedeemable") }}</span></template><span>{{ $t("AI Strategy") }}</span><span>{{ $t("US Equity") }}</span></div><button type="button" class="qf-cta" @click="openModal('subscribe',&quot;aiQuant.landing.quantFund.name&quot;,{...f,name:'AI Fund VIP '+i,symbol:'USDT'})">{{ $t("aiQuant.quantFund.card.cta") }}</button></article></div></template>

